package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
final class WorkflowInsightsAcceptance {
 static final String API="/api/openservice/insights/incident";
 static String stamp(long seconds){return DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss").withZone(ZoneOffset.UTC).format(Instant.ofEpochSecond(seconds));}
 static Map<String,Object> seed(Store store,long at)throws Exception {try(var db=store.open()){PlatformFoundationTest.bind(db);var old=Service.create(db,"incident",map("short_description","Old waiting incident <script>"),"admin");String a=old.get("sys_id").toString();db.update("UPDATE os_event SET created=? WHERE record_id=?",stamp(at-72*3600),a);Service.update(db,"incident",old,map("description","An edit does not restart state age"),"admin","admin",null);db.update("UPDATE os_event SET created=? WHERE record_id=? AND action='updated'",stamp(at-3600),a);var progressing=Service.create(db,"incident",map("short_description","Processing bounded request"),"admin");String b=progressing.get("sys_id").toString();db.update("UPDATE os_event SET created=? WHERE record_id=?",stamp(at-48*3600),b);Service.update(db,"incident",progressing,map("state","2"),"admin","admin",null);db.update("UPDATE os_event SET created=? WHERE record_id=? AND action='updated'",stamp(at-24*3600),b);String unknown=Service.create(db,"incident",map("short_description","History unavailable"),"admin").get("sys_id").toString();db.update("DELETE FROM os_event WHERE record_id=?",unknown);var terminal=Service.create(db,"incident",map("short_description","Closed incident"),"admin");for(String state:List.of("2","6","7"))Service.update(db,"incident",terminal,map("state",state),"admin","admin",null);db.connection.commit();return map("old",a,"progress",b,"unknown",unknown,"terminal",terminal.get("sys_id"));}}
 static Map<String,Object> page(WorkflowSupport h,String args,String actor)throws Exception {var response=h.get(API+args,auth(actor));assertEquals(200,response.statusCode(),html(response));return result(response);}
 static Map<String,Object> row(Map<String,Object> page,String id){return objects(page.get("records")).stream().filter(r->r.get("record_id").equals(id)).findFirst().orElseThrow();}
 static void run(WorkflowSupport h)throws Exception {long at=Instant.now().getEpochSecond();var f=seed(h.store,at);Map<String,Object> report;try(var db=h.store.open()){PlatformFoundationTest.bind(db);report=WorkflowInsights.page(db,"incident",Map.of(),at);}assertEquals(4,report.get("selected_count"));assertEquals(3,object(report.get("summary")).get("count"));assertEquals(2L,object(report.get("summary")).get("known"));assertEquals(1L,object(report.get("summary")).get("unknown"));assertEquals(2L,object(report.get("summary")).get("above_threshold"));assertEquals("48.00",object(report.get("summary")).get("mean_hours"));assertEquals("172800.00",object(report.get("summary")).get("mean_seconds"));assertEquals(259200L,object(report.get("summary")).get("max_seconds"));assertEquals(List.of(f.get("old"),f.get("progress"),f.get("unknown")),objects(report.get("records")).stream().map(r->r.get("record_id")).toList());assertEquals(2,objects(report.get("groups")).size());assertEquals("72.00",row(report,f.get("old").toString()).get("age_hours"));assertNull(row(report,f.get("unknown").toString()).get("entered_at"));assertEquals(3,object(page(h,"","admin").get("summary")).get("count"));assertEquals(2,object(page(h,"?q=state%3D1&hours=25","admin").get("summary")).get("count"));new Store(h.environment);assertEquals(3,object(page(h,"","admin").get("summary")).get("count"));assertEquals(200,h.json("PATCH","/api/now/table/incident/"+f.get("old"),map("state","2"),auth("admin")).statusCode());var changed=row(page(h,"","admin"),f.get("old").toString());assertEquals("2",changed.get("state"));assertEquals(false,changed.get("above_threshold"));assertTrue(((Number)changed.get("age_seconds")).longValue()<10);}
 static void evidence(WorkflowSupport h)throws Exception {
  long at=Instant.now().getEpochSecond();var f=seed(h.store,at);String id=f.get("old").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.readRecord(db,"incident",id);for(String value:List.of("bad timestamp","2026-02-30 10:00:00",stamp(at+1))){db.update("UPDATE os_event SET created=? WHERE record_id=? AND action='created'",value,id);assertNull(WorkflowInsights.observed(db,item,at).get("age_seconds"));}db.update("UPDATE os_event SET created=? WHERE record_id=? AND action='created'",stamp(at),id);assertEquals(0L,WorkflowInsights.observed(db,item,at).get("age_seconds"));var report=WorkflowInsights.page(db,"incident",Map.of("q","sys_id="+id,"hours","0"),at);assertEquals(true,row(report,id).get("above_threshold"));db.update("UPDATE os_event SET detail="+db.jsonParameter()+" WHERE record_id=? AND action='updated'",JSON.writeValueAsString(map("before",map("state","1"),"after",map("state","2"))),id);assertNull(WorkflowInsights.observed(db,item,at).get("age_seconds"));db.update("UPDATE os_event SET detail="+db.jsonParameter()+" WHERE record_id=? AND action='updated'",JSON.writeValueAsString(map()),id);assertNull(WorkflowInsights.observed(db,item,at).get("age_seconds"));db.update("DELETE FROM os_event WHERE record_id=? AND action='updated'",id);for(int n=0;n<500;n++)Service.audit(db,item,"admin","updated",map("before",map("state","1"),"after",map("state","1")));assertNull(WorkflowInsights.observed(db,item,at).get("age_seconds"));db.connection.rollback();}
  var onlyUnknown=page(h,"?q=sys_id%3D"+f.get("unknown"),"admin");assertNull(object(onlyUnknown.get("summary")).get("mean_hours"));assertNull(object(onlyUnknown.get("summary")).get("mean_seconds"));assertNull(object(onlyUnknown.get("summary")).get("max_seconds"));assertEquals(0,object(page(h,"?q=short_description%3DAbsent","admin").get("summary")).get("count"));
 }
 static void authorization(WorkflowSupport h)throws Exception {
  h.account("InsightsStaff","agent");h.account("InsightsOther","agent");h.account("InsightsReader","reader");h.account("InsightsRequester","requester");var f=seed(h.store,Instant.now().getEpochSecond());assertEquals(401,h.get(API,null).statusCode());for(String actor:List.of("InsightsReader","InsightsRequester"))assertEquals(403,h.get(API,auth(actor)).statusCode());ProblemInvestigationsAcceptance.access(h,"incident",f.get("old").toString(),"private",KnowledgeReviewsAcceptance.accountId(h.store,"InsightsOther"));var view=page(h,"","InsightsStaff");assertEquals(2,object(view.get("summary")).get("count"));assertFalse(JSON.writeValueAsString(view).contains(f.get("old").toString()));assertFalse(JSON.writeValueAsString(view).contains("Old waiting"));assertEquals(3,object(page(h,"","InsightsOther").get("summary")).get("count"));Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");}
  try{var hidden=new LinkedHashMap<>(schema);hidden.put("field_rules",map("short_description",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",hidden);view=page(h,"","InsightsStaff");assertEquals("Record",objects(view.get("records")).getFirst().get("label"));assertFalse(JSON.writeValueAsString(view).contains("Processing bounded request"));assertEquals(400,h.get(API+"?q=short_description%3Dsecret",auth("InsightsStaff")).statusCode());hidden.put("field_rules",map("state",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",hidden);assertEquals(403,h.get(API,auth("InsightsStaff")).statusCode());hidden.put("record_roles",map("read",List.of("reader")));ReferencePickerAcceptance.writeSchema(h,"incident",hidden);assertEquals(403,h.get(API,auth("admin")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",schema);}
 }
 static void boundaries(WorkflowSupport h)throws Exception {assertEquals(0,object(page(h,"","admin").get("summary")).get("count"));for(String q:List.of("?hours=-1","?hours=87601","?hours=x","?extra=1","?hours=1&hours=2","?q=unknown_field%3Dx"))assertEquals(400,h.get(API+q,auth("admin")).statusCode());assertEquals(200,h.get(API+"?hours=87600",auth("admin")).statusCode());assertEquals(400,h.get("/api/openservice/insights/kb_knowledge",auth("admin")).statusCode());assertEquals(404,h.get("/api/openservice/insights/missing",auth("admin")).statusCode());assertEquals(405,h.json("POST",API,map(),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=0;n<501;n++)Service.create(db,"incident",map("short_description","Capacity "+n),"admin");db.connection.commit();}assertEquals(400,h.get(API,auth("admin")).statusCode());assertEquals(1,object(page(h,"?q=short_description%3DCapacity%200","admin").get("summary")).get("count"));}
 static void tiesAndRetention(WorkflowSupport h)throws Exception {
  long at=Instant.now().getEpochSecond();String first,second;try(var db=h.store.open()){PlatformFoundationTest.bind(db);first=Service.create(db,"incident",map("short_description","First equal age"),"admin").get("sys_id").toString();second=Service.create(db,"incident",map("short_description","Second equal age"),"admin").get("sys_id").toString();db.update("UPDATE os_event SET created=? WHERE record_id IN (?,?)",stamp(at-3600),first,second);db.connection.commit();}try(var db=h.store.open()){PlatformFoundationTest.bind(db);var report=WorkflowInsights.page(db,"incident",Map.of("hours","1"),at);var sorted=new ArrayList<>(List.of(first,second));Collections.sort(sorted);assertEquals(sorted,objects(report.get("records")).stream().map(r->r.get("record_id")).toList());assertEquals(2L,object(report.get("summary")).get("above_threshold"));db.update("DELETE FROM os_event WHERE record_id IN (?,?)",first,second);db.connection.commit();}new Store(h.environment);var report=page(h,"","admin");assertEquals(2,object(report.get("summary")).get("unknown"));assertEquals(0,object(report.get("summary")).get("above_threshold"));
 }

}
